<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue';
import {api,native,on,state} from './native.js';
import Icon from './Icon.vue';import OnlinePlayers from './OnlinePlayers.vue';import AppSelect from './AppSelect.vue';
const emit=defineEmits(['open-minecraft']);
const items=ref([]),access=ref({}),grants=ref([]),uid=ref(''),busy=ref(false),working=ref(''),error=ref(''),notice=ref('');
const lobby=ref({mode:'idle',phase:'尚未连接'}),engine=ref({}),presets=ref([]),selected=ref('survival'),roomName=ref('一起玩 Minecraft'),scope=ref('internet'),method=ref('auto'),invite=ref(''),publish=ref(true),inspected=ref(null);
let timer;const off=on('lobby',v=>lobby.value=v),offEngine=on('gameEngine',v=>engine.value=v);
const active=computed(()=>lobby.value.mode==='host'||lobby.value.mode==='guest'),occupied=computed(()=>lobby.value.mode!=='idle'),presetOptions=computed(()=>presets.value.map(p=>({value:p.id,label:p.name})));
async function refresh(){if(busy.value)return;busy.value=true;try{const [a,r,l,e,p]=await Promise.all([api('/api/lobby/access'),api('/api/lobby/rooms'),native('lobby',{action:'state'}),native('gameEngine'),api('/api/server-presets')]);access.value=a;items.value=r.items||[];lobby.value=l;engine.value=e;presets.value=(p.servers||[]).filter(v=>v.enabled!==false);if(presets.value.length&&!presets.value.some(v=>v.id===selected.value))selected.value=presets.value[0].id;if(a.admin)grants.value=(await api('/api/admin/lobby/grants')).items||[];}catch(e){error.value=/404|Not Found/i.test(e.message)?'请管理员更新社区服务端后重试。':e.message;}finally{busy.value=false;}}
async function run(label,fn){if(working.value)return;working.value=label;error.value='';notice.value='';try{return await fn();}catch(e){error.value=e.message;}finally{working.value='';}}
async function copy(text){await run('copy',async()=>{await native('clipboard',{text});notice.value='邀请已复制，手机和电脑均可在联机大厅加入';});}
async function host(){await run('host',async()=>{lobby.value=await native('lobby',{action:'host',name:roomName.value,scope:scope.value,method:method.value,public:publish.value,instance:selected.value});notice.value='房间已创建。启动游戏并进入单人世界后，会自动向伙伴开放。';});}
async function join(text=invite.value){await run('join',async()=>{const info=await native('lobby',{action:'inspect',invite:text,method:method.value});inspected.value=info;if(!info.ready)throw Error('已连接房主，世界尚未开放，请稍后再试');const preset=String(info.game?.preset||'');const id=presets.value.find(p=>p.id===preset||p.id==='HXZ-'+preset)?.id;if(!id)throw Error('房间尚未提供可匹配的默认游戏配置，请让房主启动游戏后刷新邀请');selected.value=id;lobby.value=await native('lobby',{action:'join',invite:text,method:method.value,instance:id});notice.value='直连通道已就绪，点击「进入房间游戏」启动相同版本。';});}
async function close(){await run('close',async()=>{lobby.value=await native('lobby',{action:'close'});inspected.value=null;});}
async function launch(){await run('launch',async()=>{if(!engine.value.riskAccepted)throw Error('请先前往 Minecraft 页面阅读并确认手机游戏运行提示');let options={};try{options=JSON.parse(localStorage.getItem('hxz-mobile-game')||'{}');}catch{}engine.value=await native('gameEngine',{action:'launch',id:lobby.value.room?.instance||lobby.value.guest?.instance||selected.value,room:true,expectedGame:inspected.value?.game||null,options:{...options,autoJoin:lobby.value.mode==='guest'}});if(engine.value.busy)notice.value='正在准备游戏运行资源，完成后会继续启动房间游戏。';});}
async function grant(id,remove=false){await run('grant',async()=>{await api('/api/admin/lobby/grants','POST',{uid:id,enabled:!remove});uid.value='';await refresh();});}
onMounted(()=>{void refresh();timer=setInterval(()=>{if(!document.hidden&&!working.value)void refresh();},20000);});onBeforeUnmount(()=>{clearInterval(timer);off();offEngine();});
</script>
<template><section class="content-page lobby-page">
 <header class="page-toolbar"><h1>MC 联机大厅</h1><button class="icon-button" aria-label="刷新联机房间" :disabled="busy" @click="refresh"><Icon name="refresh"/></button></header>
 <p class="lobby-intro">手机与电脑一起玩。游戏通过 P2P 或 IPv4 / IPv6 加密直连房主，社区仅验证权限与协商连接。</p>
 <p v-if="error||lobby.error" class="card error-note" role="alert">{{error||lobby.error}}</p><p v-if="notice" class="card lobby-notice" role="status">{{notice}}</p>
 <section v-if="occupied" class="card lobby-session"><header class="mobile-card-heading"><h2>{{lobby.mode==='host'?'我创建的房间':lobby.mode==='guest'?'已连接的房间':'正在建立连接'}}</h2><span class="tag">{{lobby.transport==='p2p'?'P2P':lobby.transport==='direct'?'加密直连':'连接中'}}</span></header><h3>{{lobby.room?.name||lobby.guest?.name}}</h3><p aria-live="polite">{{lobby.phase}}</p><p v-if="lobby.mode==='host'" class="muted">{{lobby.connections||0}} 个连接 · {{lobby.listed?'已显示在大厅':'邀请加入'}} · {{lobby.ready?'世界已开放':'等待进入单人世界'}}</p><div class="lobby-actions"><button v-if="active" class="primary" :disabled="!!working||engine.busy" @click="launch"><Icon name="play"/>{{lobby.mode==='host'?'启动房主游戏':'进入房间游戏'}}</button><button v-if="lobby.room?.invite" class="soft-button" :disabled="!!working" @click="copy(lobby.room.invite)">复制邀请</button><button class="soft-button danger-text" :disabled="!!working" @click="close">{{lobby.mode==='host'?'关闭房间':'离开连接'}}</button></div><div v-if="active&&!engine.riskAccepted" class="lobby-risk-link"><span>首次运行需先阅读并确认手机游戏运行提示。</span><button class="soft-button" @click="emit('open-minecraft')">前往 Minecraft 阅读提示</button></div><small v-if="active">{{lobby.mode==='host'?'进入自己的单人世界，启动器会自动开放联机。':'启动后自动连接本机加密通道。'}}缺少运行资源时会在社区应用内自动准备；切换页面会保留连接，可从系统通知断开。</small></section>
 <section v-if="!occupied" class="card form-stack"><header class="mobile-card-heading"><h2>加入伙伴</h2><span class="tag">手机 / 电脑</span></header><label>房间邀请<textarea v-model="invite" rows="3" maxlength="16000" placeholder="粘贴 hxz-room://join/…" spellcheck="false" autocapitalize="off"/></label><label>连接方式<AppSelect v-model="method" label="加入连接方式" :options="[{value:'auto',label:'自动连接 · 直连优先'},{value:'p2p',label:'P2P 点对点'},{value:'ipv4',label:'IPv4 直连'},{value:'ipv6',label:'IPv6 直连'}]"/></label><button class="primary" :disabled="!!working||!invite.trim()||!state.hasAccount" @click="join()"><Icon name="play"/>{{working==='join'?'正在验证房间…':'验证并加入房间'}}</button></section>
 <section class="card"><header class="mobile-card-heading"><h2>正在联机的房间</h2><span class="tag">{{items.length}}</span></header><p v-if="!items.length" class="empty-note">{{busy?'正在读取房间…':'暂时没有公开房间，可粘贴伙伴的邀请加入'}}</p><article v-for="r in items" :key="r.id" class="lobby-room"><div><h3>{{r.name}}</h3><p>{{r.owner}} · {{r.version||'版本待确认'}} {{r.loader}}</p><small>{{r.ready?'世界已开放':'等待房主进入世界'}} · {{r.connections}} 个连接 · {{r.scope==='lan'?'局域网':r.scope==='virtual'?'虚拟局域网':'互联网'}}</small></div><div class="lobby-room-actions"><button class="primary" :disabled="!r.ready||!!working||occupied||!state.hasAccount" @click="join(r.invite)">加入</button><button class="soft-button" :disabled="!!working" @click="copy(r.invite)">复制邀请</button></div></article></section>
 <section v-if="!occupied" class="card form-stack"><h2>用手机创建房间</h2><p v-if="!access.canHost" class="muted">需要管理员授予开房权限；加入伙伴的房间无需开房权限。</p><template v-else><label>房间名称<input v-model="roomName" maxlength="80" placeholder="一起玩 Minecraft"></label><label>游戏配置<AppSelect v-model="selected" label="房主游戏配置" :options="presetOptions"/></label><label>网络范围<AppSelect v-model="scope" label="房间网络范围" :options="[{value:'internet',label:'互联网 · P2P / 公网直连'},{value:'lan',label:'同一局域网 · Wi-Fi / 热点'}]"/></label><label class="lobby-switch"><span>在大厅公开显示</span><input v-model="publish" type="checkbox"></label><p class="muted">异地 P2P 取决于双方网络；手机暂不自动映射路由器端口。同一 Wi-Fi 或热点可使用局域网模式。</p><button class="primary" :disabled="!!working||!roomName.trim()||!presets.length||!state.hasAccount" @click="host">{{working==='host'?'正在创建…':'创建房间'}}</button></template></section>
 <OnlinePlayers/>
 <section v-if="access.admin" class="card form-stack"><h2>开房授权</h2><form class="form-stack" @submit.prevent="grant(uid)"><label>用户 UID<input v-model="uid" required maxlength="100"></label><button class="primary" :disabled="!!working||!uid.trim()">授予创建权限</button></form><div v-for="g in grants" :key="g.uid" class="lobby-room"><span>{{g.name||g.uid}}</span><button class="text-button danger-text" :disabled="!!working" @click="grant(g.uid,true)">撤销授权</button></div></section>
</section></template>
<style scoped>
.lobby-page{display:grid;gap:16px}.lobby-page>*,.lobby-page p,.lobby-page h2,.lobby-page h3{margin:0;min-width:0}.lobby-intro,.lobby-page small,.lobby-page .muted{font-size:.84rem;line-height:1.75;color:var(--muted)}.lobby-page h2{font-size:1rem}.lobby-page h3{font-size:.95rem;line-height:1.6;overflow-wrap:anywhere}.lobby-page .card{min-width:0}.lobby-page .form-stack{gap:14px}.lobby-page label{display:grid;gap:8px;min-width:0;font-size:.88rem}.lobby-page textarea{width:100%;resize:vertical;min-height:84px;font-size:.84rem;overflow-wrap:anywhere}.lobby-session{display:grid;gap:12px}.lobby-actions,.lobby-room-actions{display:flex;flex-wrap:wrap;gap:8px}.lobby-actions>button{flex:1 1 120px;min-height:44px}.lobby-risk-link{display:grid;gap:8px;font-size:.84rem;line-height:1.7;color:var(--muted)}.lobby-risk-link>button{justify-self:start;min-height:44px}.lobby-room{display:flex;gap:12px;flex-wrap:wrap;align-items:center;justify-content:space-between;padding:16px 0;border-bottom:1px solid var(--line)}.lobby-room:last-child{border-bottom:0;padding-bottom:0}.lobby-room>div:first-child{flex:1 1 180px;min-width:0}.lobby-room p{font-size:.84rem;color:var(--muted);line-height:1.7;overflow-wrap:anywhere}.lobby-room-actions>button{min-height:42px}.lobby-page .lobby-switch{display:flex;align-items:center;justify-content:space-between;gap:12px}.lobby-switch>input{width:24px;height:24px;min-height:24px}.lobby-notice{line-height:1.7;color:var(--accent)}.lobby-page .primary{min-height:44px}.lobby-page .error-note{line-height:1.75;overflow-wrap:anywhere}
</style>
